const value = $json.output ?? $json;
const allowedReasons = ['briefing_complete','human_requested','negotiation','complaint','urgency','low_confidence','unsupported'];
const confidence = Math.max(0, Math.min(1, Number(value.confidence ?? 0)));
const mustHandoff = Boolean(value.handoff_required) || confidence < 0.65;
return { json: {
  reply_text: String(value.reply_text ?? 'Vou encaminhar seu atendimento para nossa equipe.'),
  intent: ['faq','quote_interest','order_status','complaint','other'].includes(value.intent) ? value.intent : 'other',
  segment: ['uniform','event_abada','sport','own_brand','unknown'].includes(value.segment) ? value.segment : 'unknown',
  lead_patch: value.lead_patch && typeof value.lead_patch === 'object' ? value.lead_patch : {},
  missing_fields: Array.isArray(value.missing_fields) ? value.missing_fields : [],
  handoff_required: mustHandoff,
  handoff_reason: mustHandoff ? (allowedReasons.includes(value.handoff_reason) ? value.handoff_reason : 'low_confidence') : null,
  confidence,
  reasoning: String(value.reasoning ?? '').slice(0, 300),
  conversation_id: $('Montar contexto do agente').item.json.conversation_id,
  wa_id: $('Montar contexto do agente').item.json.wa_id,
  phone_number_id: $('Montar contexto do agente').item.json.phone_number_id
} };

const decision = $('Normalizar decisão da IA').item.json;
const reservation = $('Preparar reserva de envio da IA').item.json.payload;
const messageId = $json.messages?.[0]?.id ?? ('out-' + reservation.command_id);
const eventType = decision.handoff_required ? 'handoff.requested' : 'message.sent';
const payload = { schema_version: '1.0', event_id: messageId, event_type: eventType,
  occurred_at: new Date().toISOString(), conversation_id: decision.conversation_id,
  automation_epoch: reservation.automation_epoch, revision: reservation.revision,
  expected_version: reservation.expected_version, claim_id: reservation.claim_id,
  claim_token: reservation.claim_token, command_id: reservation.command_id,
  ai_provider: reservation.ai_provider, ai_model: reservation.ai_model, prompt_version: reservation.prompt_version,
  message: { external_id: messageId, sender_type: 'ai', type: 'text', text: decision.reply_text },
  lead_patch: decision.lead_patch,
  handoff: decision.handoff_required ? { reason: decision.handoff_reason, mode: 'handoff_pending', missing_fields: decision.missing_fields } : null };
return { json: { payload, idempotency_key: reservation.command_id + ':' + eventType } };

const headers = $json.headers ?? {};
const payload = $json.body && typeof $json.body === 'object' ? $json.body : {};
const idempotencyKey = String(headers['idempotency-key'] ?? '');
return { json: { payload, idempotency_key: idempotencyKey,
  parse_valid: Boolean($json.body && typeof $json.body === 'object'),
  schema_valid: payload.schema_version === '1.0',
  idempotency_valid: Boolean(payload.command_id) && idempotencyKey === payload.command_id } };

const execution = $json.execution ?? {};
const error = execution.error ?? $json.error ?? {};
return { json: { event_id: 'failure:' + (execution.id ?? $execution.id), conversation_id: '',
  stage: execution.lastNodeExecuted ?? 'workflow',
  error_code: String(error.name ?? 'WORKFLOW_ERROR').slice(0, 80),
  retry_count: 0, created_at: new Date().toISOString() } };

const mime = String($json.mime_type ?? '').toLowerCase();
const size = Number($json.file_size ?? 0);
const imageTypes = ['image/jpeg','image/png','image/webp'];
const audioTypes = ['audio/aac','audio/amr','audio/mpeg','audio/mp4','audio/ogg','audio/opus'];
const videoTypes = ['video/mp4','video/3gpp'];
const documentTypes = ['application/pdf','text/plain','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.ms-excel','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','application/vnd.ms-powerpoint','application/vnd.openxmlformats-officedocument.presentationml.presentation'];
const allowedType = imageTypes.includes(mime) || audioTypes.includes(mime) || videoTypes.includes(mime) || documentTypes.includes(mime);
const defaultLimit = imageTypes.includes(mime) ? 5 * 1024 * 1024 : (audioTypes.includes(mime) || videoTypes.includes(mime)) ? 16 * 1024 * 1024 : 100 * 1024 * 1024;
const panelLimit = Number($env.SILMER_MAX_ATTACHMENT_BYTES ?? defaultLimit);
const effectiveLimit = Math.min(defaultLimit, Number.isFinite(panelLimit) && panelLimit > 0 ? panelLimit : defaultLimit);
const mediaAllowed = allowedType && size > 0 && size <= effectiveLimit;
return { json: { ...$json, media_allowed: mediaAllowed, media_rejection_reason: !allowedType ? 'unsupported_mime_type' : size <= 0 ? 'invalid_file_size' : size > effectiveLimit ? 'file_too_large' : null, effective_limit_bytes: effectiveLimit } };

const claim = $('Painel - Reivindicar rodada da IA').item.json;
const inbound = $('Normalizar evento WhatsApp').item.json;
return { json: {
  conversation_id: claim.conversation_id,
  wa_id: inbound.from,
