const messageId = $json.messages?.[0]?.id ?? ('fallback-' + reservation.command_id);
const payload = { schema_version: '1.0', event_id: messageId, event_type: 'handoff.requested',
  occurred_at: new Date().toISOString(), conversation_id: fallback.conversation_id,
  automation_epoch: reservation.automation_epoch, revision: reservation.revision,
