  ai_provider: reservation.ai_provider, ai_model: reservation.ai_model, prompt_version: reservation.prompt_version,
  message: { external_id: messageId, sender_type: 'ai', type: 'text', text: fallback.reply_text },
  lead_patch: {}, handoff: { reason: 'low_confidence', mode: 'handoff_pending', missing_fields: [] } };
return { json: { payload, idempotency_key: reservation.command_id + ':handoff.requested' } };

const failure = $('Normalizar falha').item.json;
const payload = { schema_version: '1.0', event_id: failure.event_id + ':panel',
  event_type: 'workflow.failed', occurred_at: failure.created_at, conversation_id: failure.conversation_id || null,
  failure: { stage: failure.stage, code: failure.error_code, retry_count: failure.retry_count } };
return { json: { payload, idempotency_key: payload.event_id } };

const command = $('Decodificar comando do painel').item.json.payload;
const messageId = $json.messages?.[0]?.id ?? ('human-' + command.command_id);
const payload = { schema_version: '1.0', event_id: messageId, event_type: 'message.sent',
  occurred_at: new Date().toISOString(), conversation_id: command.conversation_id,
  automation_epoch: command.automation_epoch, command_id: command.command_id,
